#include "api.h"
typedef int scalar_t;
struct meter { int member; };
union payload { int amount; };
enum phase { PENDING = 1 };
int calculate(int input) {
    scalar_t value = input;
    struct meter item = { .member = value };
    union payload box = { .amount = item.member };
    enum phase state = PENDING;
    return box.amount + state;
}

