#include "api.h"
typedef long scalar_t;
struct meter { double other; };
union payload { double other; };
enum phase { OTHER = 2 };
int main(void) {
    scalar_t value = 3;
    struct meter item = { .other = 0.0 };
    union payload box = { .other = item.other };
    enum phase state = OTHER;
    return calculate((int)value) + (int)box.other + state;
}

